process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — copy a calculating version into a static member
# Prolog: validate, create pTarget, parent it under Non-Calculating, mark Static.
# Epilog: copy the cells (runs AFTER the Prolog commits the parent edge, so the
# [] STET/CONTINUE guard is active for pTarget and CellPutN is allowed).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Static', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' - ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );
   IF( ELISANC( cVer, 'Non-Calculating', pTarget ) = 0 );
      DimensionElementComponentAdd( cVer, 'Non-Calculating', pTarget, 1 );
   ENDIF;
ENDIF;

process::WFP Snapshot Version.EpilogProcedure:
#Region WFP Snapshot Version — Epilog: copy cells (parent edge now committed)
IF( nStop = 0 );
   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cWI, vP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Hiring Plan : Position x Measure (Version fixed) ---
   cHP = 'WFP Hiring Plan';
   nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Hiring Plan Measure' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         nK = 1;
         WHILE( nK <= nC );
            vM = DIMNM( 'WFP Hiring Plan Measure', nK );
            IF( DTYPE( 'WFP Hiring Plan Measure', vM ) @= 'N' );
               nVal = CellGetN( cHP, pSource, vPos, vM );
               IF( nVal <> 0 ); CellPutN( nVal, cHP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
            ENDIF;
            nK = nK + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cAS, vP, pTarget, vEnt, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 ); CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM ); nCopied = nCopied + 1; ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 ); CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM ); nCopied = nCopied + 1; ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Workforce Cost + WFP Headcount OUTPUT : per position ---
   # P5: copy Amount / Amount Capex / Amount Opex at salary currency, Reporting and
   # Reporting @ Budget FX so the snapshot freezes the full restated P&L view.
   cWC = 'WFP Workforce Cost'; cHC = 'WFP Headcount';
   vPCs = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
   vHMs = 'Headcount|FTE|Open Positions|Hires|Leavers|Opening|Closing|';
   nB = DIMSIZ( 'WFP Position' ); nA = DIMSIZ( 'WFP Period' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         vEnt = ATTRS( 'WFP Position', vPos, 'Home Entity' );
         vCC  = ATTRS( 'WFP Position', vPos, 'Cost Centre' );
         vSC  = ATTRS( 'WFP Position', vPos, 'Salary Currency' );
         nI = 1;
         WHILE( nI <= nA );
            vP = DIMNM( 'WFP Period', nI );
            IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
               vL = vPCs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  vCurL = vSC | '|Reporting|Reporting @ Budget FX|';
                  WHILE( SCAN( '|', vCurL ) > 1 );
                     nS = SCAN( '|', vCurL ); vCurX = SUBST( vCurL, 1, nS - 1 ); vCurL = SUBST( vCurL, nS + 1, LONG( vCurL ) - nS );
                     vMeaL = 'Amount|Amount Capex|Amount Opex|';
                     WHILE( SCAN( '|', vMeaL ) > 1 );
                        nS = SCAN( '|', vMeaL ); vMeaX = SUBST( vMeaL, 1, nS - 1 ); vMeaL = SUBST( vMeaL, nS + 1, LONG( vMeaL ) - nS );
                        nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, vCurX, vPos, vMeaX );
                        IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, vCurX, vPos, vMeaX ); nCopied = nCopied + 1; ENDIF;
                     END;
                  END;
               END;
               vL = vHMs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vHM = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cHC, vP, pSource, vEnt, vCC, vPos, vHM );
                  IF( nVal <> 0 ); CellPutN( nVal, cHC, vP, pTarget, vEnt, vCC, vPos, vHM ); nCopied = nCopied + 1; ENDIF;
               END;
            ENDIF;
            nI = nI + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' cells copied. ' | pTarget | ' is Static under Non-Calculating.' );
ENDIF;

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets attribute VALUES that were built declaratively and do not survive a deploy.
# Idempotent.

# --- WFP Period: Period Index, Days In Month, Prior Period, Next Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 ); nDays = 28; ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 ); nDays = 30; ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      IF( vPrev @<> '' );
         AttrPutS( vPer, cPer, vPrev, 'Next Period' );
      ENDIF;
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;
# last period: Next Period points to itself (keeps the forward feeder valid)
IF( vPrev @<> '' );
   AttrPutS( vPrev, cPer, vPrev, 'Next Period' );
ENDIF;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' ); AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' ); ENDIF;
      IF( vPL @<> '' ); AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' ); ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Static), Description ---
vVr = 'Actual;Static;Actuals - non-calculating; populated by the payroll load (Phase 7)~Budget;Calculated;Approved plan being built~Forecast;Calculated;Working current model - closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

# --- WFP Pay Component: GL Account (P5 - P&L / GL mapping) ---
# Leaf pay components -> GL account code. GL rollup nodes carry the code too.
vPC = 'Base;6000~One-Time;6010~Bonus;6100~Employer Payroll Tax;6200~Employer Pension;6300~Benefits;6400~Employee Income Tax;7100~Employee Pension;7200~';
WHILE( SCAN( '~', vPC ) > 1 );
   nS = SCAN( '~', vPC ); vRec = SUBST( vPC, 1, nS - 1 ) | ';'; vPC = SUBST( vPC, nS + 1, LONG( vPC ) - nS );
   nS = SCAN( ';', vRec ); vEl  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vGL  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Pay Component', vEl ) > 0 );
      AttrPutS( vGL, 'WFP Pay Component', vEl, 'GL Account' );
   ENDIF;
END;
IF( DIMIX( 'WFP Pay Component', 'GL: Salaries & Wages' ) > 0 );
   AttrPutS( '6000', 'WFP Pay Component', 'GL: Salaries & Wages', 'GL Account' );
   AttrPutS( '6100', 'WFP Pay Component', 'GL: Bonus & Incentives', 'GL Account' );
   AttrPutS( '6200', 'WFP Pay Component', 'GL: Employer Payroll Taxes', 'GL Account' );
   AttrPutS( '6300', 'WFP Pay Component', 'GL: Employer Pension', 'GL Account' );
   AttrPutS( '6400', 'WFP Pay Component', 'GL: Benefits', 'GL Account' );
ENDIF;

# --- WFP Cost Centre: Capex % (P5 - share of loaded Cost-to-Company capitalised) ---
# R&D engineering / product cost centres capitalise 18% of CtC; everything else 0.
vCX = 'CC-ENG-PLT;0.18~CC-ENG-APP;0.18~CC-PROD;0.18~CC-SALES;0~CC-SALESOPS;0~CC-MKT;0~CC-CS;0~CC-FIN;0~CC-PPL;0~CC-ITOPS;0~CC-EXEC;0~';
WHILE( SCAN( '~', vCX ) > 1 );
   nS = SCAN( '~', vCX ); vRec = SUBST( vCX, 1, nS - 1 ) | ';'; vCX = SUBST( vCX, nS + 1, LONG( vCX ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPct = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutN( nPct, 'WFP Cost Centre', vCtr, 'Capex %' );
   ENDIF;
END;
#EndRegion

rules::WFP Headcount.rules:
SKIPCHECK;

# Non-calculating versions (Actual + snapshots) hold stored data.
[] = N: IF(ELPAR('WFP Version', !WFP Version, 1) @= 'Non-Calculating', STET, CONTINUE);

# WFP Headcount dims: Period, Version, Entity, Cost Centre, Position, Measure
# Phase 4: active window is version-aware — WFP Hiring Plan Hire/Attrition Month
# for the version, falling back to Start/End Period attrs when the plan cell is 0.
# TBH positions with no plan hire are never active.

['_Start Idx'] = N:
  IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0,
      DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'),
      IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'TBH', 9999,
          ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index') ) );

['_Leave Idx'] = N:
  IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Attrition Month') > 0,
      DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Attrition Month'),
      IF( ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 9999,
          ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index') + 1 ) );

['_End Idx'] = N: ['_Leave Idx'] - 1;

['_Hire Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled',
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index'),
      IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0,
          DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'), 0 ) );

['_Active'] = N:
  IF( !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre')
      & ATTRN('WFP Period', !WFP Period, 'Period Index') >= ['_Start Idx']
      & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Idx'],
      1, 0 );

['_Filled Now'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled', 1,
      IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0
          & ATTRN('WFP Period', !WFP Period, 'Period Index') >= DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'), 1, 0 ) );

['Headcount'] = N: ['_Active'] * ['_Filled Now'];

['FTE'] = N:
  ['_Active'] * ATTRN('WFP Position', !WFP Position, 'FTE')
  * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'TBH', ['_Filled Now'], 1 );

['Open Positions'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Open Req',
                    IF( ['_Filled Now'] = 1, 0, 1 ), 0 );

['Hires'] = N:
  IF( ['_Hire Idx'] >= 13
      & ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_Hire Idx']
      & ['_Active'] = 1, 1, 0 );

['Leavers'] = N:
  IF( ['_Leave Idx'] < 9999
      & ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_Leave Idx']
      & !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre'), 1, 0 );

['Opening'] = N:
  IF( ATTRS('WFP Period', !WFP Period, 'Prior Period') @= '', 0,
      DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Prior Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Headcount') );

['Closing'] = N: ['Opening'] + ['Hires'] - ['Leavers'];

FEEDERS;

['Headcount'] => ['FTE'], ['Open Positions'], ['Hires'], ['Opening'], ['Closing'];
['FTE']       => ['Open Positions'], ['Opening'], ['Closing'];
# Leavers fire the month AFTER headcount drops to 0 — feed forward via Next Period.
['Headcount'] => DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Leavers'),
                 DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Closing');

process::WFP Snapshot Version.PrologProcedure:
#Region WFP Snapshot Version — copy a calculating version into a static member
# Prolog: validate, create pTarget, parent it under Non-Calculating, mark Static.
# Epilog: copy the cells (runs AFTER the Prolog commits the parent edge, so the
# [] STET/CONTINUE guard is active for pTarget and CellPutN is allowed).
cVer = 'WFP Version';

nStop = 0;
IF( DIMIX( cVer, pSource ) = 0 );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Source version not found: ' | pSource );
   nStop = 1;
ENDIF;
IF( nStop = 0 & ATTRS( cVer, pSource, 'Version Type' ) @<> 'Calculated' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Refused: source "' | pSource | '" is not a Calculated version.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & TRIM( pTarget ) @= '' );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target member name is blank.' );
   nStop = 1;
ENDIF;
IF( nStop = 0 & pTarget @= pSource );
   ASCIIOUTPUT( 'WFP_Snapshot_error.txt', 'Target equals source.' );
   nStop = 1;
ENDIF;

IF( nStop = 0 );
   IF( DIMIX( cVer, pTarget ) = 0 );
      DimensionElementInsertDirect( cVer, '', pTarget, 'N' );
   ENDIF;
   AttrPutS( 'Static', cVer, pTarget, 'Version Type' );
   AttrPutS( 'Snapshot of ' | pSource | ' - ' | TIMST( NOW, '\Y-\m-\d' ), cVer, pTarget, 'Description' );
   IF( ELISANC( cVer, 'Non-Calculating', pTarget ) = 0 );
      DimensionElementComponentAdd( cVer, 'Non-Calculating', pTarget, 1 );
   ENDIF;
ENDIF;

process::WFP Snapshot Version.EpilogProcedure:
#Region WFP Snapshot Version — Epilog: copy cells (parent edge now committed)
IF( nStop = 0 );
   nCopied = 0;

   # --- WFP Workforce Input : Period x Position x Measure ---
   cWI = 'WFP Workforce Input';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Workforce Input Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vPos = DIMNM( 'WFP Position', nJ );
            IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Workforce Input Measure', nK );
                  IF( DTYPE( 'WFP Workforce Input Measure', vM ) @= 'N' );
                     nVal = CellGetN( cWI, vP, pSource, vPos, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cWI, vP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Hiring Plan : Position x Measure (Version fixed) ---
   cHP = 'WFP Hiring Plan';
   nB = DIMSIZ( 'WFP Position' ); nC = DIMSIZ( 'WFP Hiring Plan Measure' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         nK = 1;
         WHILE( nK <= nC );
            vM = DIMNM( 'WFP Hiring Plan Measure', nK );
            IF( DTYPE( 'WFP Hiring Plan Measure', vM ) @= 'N' );
               nVal = CellGetN( cHP, pSource, vPos, vM );
               IF( nVal <> 0 ); CellPutN( nVal, cHP, pTarget, vPos, vM ); nCopied = nCopied + 1; ENDIF;
            ENDIF;
            nK = nK + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   # --- WFP Assumptions : Period x Entity x Measure ---
   cAS = 'WFP Assumptions';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Entity' ); nC = DIMSIZ( 'WFP Assumptions Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vEnt = DIMNM( 'WFP Entity', nJ );
            IF( DTYPE( 'WFP Entity', vEnt ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vM = DIMNM( 'WFP Assumptions Measure', nK );
                  IF( DTYPE( 'WFP Assumptions Measure', vM ) @= 'N' );
                     nVal = CellGetN( cAS, vP, pSource, vEnt, vM );
                     IF( nVal <> 0 ); CellPutN( nVal, cAS, vP, pTarget, vEnt, vM ); nCopied = nCopied + 1; ENDIF;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP FX Rates : Period x Currency x FX Rate Type x Measure ---
   cFX = 'WFP FX Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Currency' ); nC = DIMSIZ( 'WFP FX Rate Type' ); nD = DIMSIZ( 'WFP FX Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vCur = DIMNM( 'WFP Currency', nJ );
            IF( DTYPE( 'WFP Currency', vCur ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vRt = DIMNM( 'WFP FX Rate Type', nK );
                  IF( DTYPE( 'WFP FX Rate Type', vRt ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 ); CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM ); nCopied = nCopied + 1; ENDIF;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Pay Rates : Period x Grade x Job Family x Location x Measure ---
   cPR = 'WFP Pay Rates';
   nA = DIMSIZ( 'WFP Period' ); nB = DIMSIZ( 'WFP Grade' ); nC = DIMSIZ( 'WFP Job Family' ); nD = DIMSIZ( 'WFP Location' ); nE = DIMSIZ( 'WFP Pay Rates Measure' );
   nI = 1;
   WHILE( nI <= nA );
      vP = DIMNM( 'WFP Period', nI );
      IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
         nJ = 1;
         WHILE( nJ <= nB );
            vG = DIMNM( 'WFP Grade', nJ );
            IF( DTYPE( 'WFP Grade', vG ) @= 'N' );
               nK = 1;
               WHILE( nK <= nC );
                  vJF = DIMNM( 'WFP Job Family', nK );
                  IF( DTYPE( 'WFP Job Family', vJF ) @= 'N' );
                     nL = 1;
                     WHILE( nL <= nD );
                        vLoc = DIMNM( 'WFP Location', nL );
                        IF( DTYPE( 'WFP Location', vLoc ) @= 'N' );
                           nMx = 1;
                           WHILE( nMx <= nE );
                              vM = DIMNM( 'WFP Pay Rates Measure', nMx );
                              IF( DTYPE( 'WFP Pay Rates Measure', vM ) @= 'N' );
                                 nVal = CellGetN( cPR, vP, pSource, vG, vJF, vLoc, vM );
                                 IF( nVal <> 0 ); CellPutN( nVal, cPR, vP, pTarget, vG, vJF, vLoc, vM ); nCopied = nCopied + 1; ENDIF;
                              ENDIF;
                              nMx = nMx + 1;
                           END;
                        ENDIF;
                        nL = nL + 1;
                     END;
                  ENDIF;
                  nK = nK + 1;
               END;
            ENDIF;
            nJ = nJ + 1;
         END;
      ENDIF;
      nI = nI + 1;
   END;

   # --- WFP Workforce Cost + WFP Headcount OUTPUT : per position ---
   # P5: copy Amount / Amount Capex / Amount Opex at salary currency, Reporting and
   # Reporting @ Budget FX so the snapshot freezes the full restated P&L view.
   cWC = 'WFP Workforce Cost'; cHC = 'WFP Headcount';
   vPCs = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
   vHMs = 'Headcount|FTE|Open Positions|Hires|Leavers|Opening|Closing|';
   nB = DIMSIZ( 'WFP Position' ); nA = DIMSIZ( 'WFP Period' );
   nJ = 1;
   WHILE( nJ <= nB );
      vPos = DIMNM( 'WFP Position', nJ );
      IF( DTYPE( 'WFP Position', vPos ) @= 'N' );
         vEnt = ATTRS( 'WFP Position', vPos, 'Home Entity' );
         vCC  = ATTRS( 'WFP Position', vPos, 'Cost Centre' );
         vSC  = ATTRS( 'WFP Position', vPos, 'Salary Currency' );
         nI = 1;
         WHILE( nI <= nA );
            vP = DIMNM( 'WFP Period', nI );
            IF( DTYPE( 'WFP Period', vP ) @= 'N' & LONG( vP ) = 7 );
               vL = vPCs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  vCurL = vSC | '|Reporting|Reporting @ Budget FX|';
                  WHILE( SCAN( '|', vCurL ) > 1 );
                     nS = SCAN( '|', vCurL ); vCurX = SUBST( vCurL, 1, nS - 1 ); vCurL = SUBST( vCurL, nS + 1, LONG( vCurL ) - nS );
                     vMeaL = 'Amount|Amount Capex|Amount Opex|';
                     WHILE( SCAN( '|', vMeaL ) > 1 );
                        nS = SCAN( '|', vMeaL ); vMeaX = SUBST( vMeaL, 1, nS - 1 ); vMeaL = SUBST( vMeaL, nS + 1, LONG( vMeaL ) - nS );
                        nVal = CellGetN( cWC, vP, pSource, vEnt, vCC, vPC, vCurX, vPos, vMeaX );
                        IF( nVal <> 0 ); CellPutN( nVal, cWC, vP, pTarget, vEnt, vCC, vPC, vCurX, vPos, vMeaX ); nCopied = nCopied + 1; ENDIF;
                     END;
                  END;
               END;
               vL = vHMs;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vHM = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nVal = CellGetN( cHC, vP, pSource, vEnt, vCC, vPos, vHM );
                  IF( nVal <> 0 ); CellPutN( nVal, cHC, vP, pTarget, vEnt, vCC, vPos, vHM ); nCopied = nCopied + 1; ENDIF;
               END;
            ENDIF;
            nI = nI + 1;
         END;
      ENDIF;
      nJ = nJ + 1;
   END;

   ASCIIOUTPUT( 'WFP_Snapshot_ok.txt', 'Snapshot ' | pSource | ' -> ' | pTarget | ' : ' | NUMBERTOSTRING( nCopied ) | ' cells copied. ' | pTarget | ' is Static under Non-Calculating.' );
ENDIF;

process::WFP Seed Dimension Attributes.PrologProcedure:
#Region WFP Seed Dimension Attributes
# Sets attribute VALUES that were built declaratively and do not survive a deploy.
# Idempotent.

# --- WFP Period: Period Index, Days In Month, Prior Period, Next Period, FY ---
cPer   = 'WFP Period';
nCount = DIMSIZ( cPer );
nIdx   = 0;
vPrev  = '';
nE = 1;
WHILE( nE <= nCount );
   vPer = DIMNM( cPer, nE );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = nIdx + 1;
      nMon = NUMBR( SUBST( vPer, 6, 2 ) );
      nDays = 31;
      IF( nMon = 2 ); nDays = 28; ENDIF;
      IF( nMon = 4 % nMon = 6 % nMon = 9 % nMon = 11 ); nDays = 30; ENDIF;
      AttrPutN( nIdx,  cPer, vPer, 'Period Index' );
      AttrPutN( nDays, cPer, vPer, 'Days In Month' );
      AttrPutS( vPrev, cPer, vPer, 'Prior Period' );
      AttrPutS( 'FY' | SUBST( vPer, 1, 4 ), cPer, vPer, 'FY' );
      IF( vPrev @<> '' );
         AttrPutS( vPer, cPer, vPrev, 'Next Period' );
      ENDIF;
      vPrev = vPer;
   ENDIF;
   nE = nE + 1;
END;
# last period: Next Period points to itself (keeps the forward feeder valid)
IF( vPrev @<> '' );
   AttrPutS( vPrev, cPer, vPrev, 'Next Period' );
ENDIF;

# --- WFP Job Family: Pay Index ---
vJF = 'Engineering;1.1~Product;1.08~Sales;1.05~Marketing;1~Customer Success;0.98~Finance;1~People;0.98~IT;1~Admin;0.92~Leadership;1.15~';
WHILE( SCAN( '~', vJF ) > 1 );
   nS = SCAN( '~', vJF ); vRec = SUBST( vJF, 1, nS - 1 ) | ';'; vJF = SUBST( vJF, nS + 1, LONG( vJF ) - nS );
   nS = SCAN( ';', vRec ); vFam = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPi  = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Job Family', vFam ) > 0 );
      AttrPutN( nPi, 'WFP Job Family', vFam, 'Pay Index' );
   ENDIF;
END;

# --- WFP Entity: Local Currency, Primary Location, Reporting Currency ---
vEn = 'Group;;;GBP~UK Ltd;GBP;London;GBP~US Inc;USD;New York;GBP~NZ Ltd;NZD;Auckland;GBP~';
WHILE( SCAN( '~', vEn ) > 1 );
   nS = SCAN( '~', vEn ); vRec = SUBST( vEn, 1, nS - 1 ) | ';'; vEn = SUBST( vEn, nS + 1, LONG( vEn ) - nS );
   nS = SCAN( ';', vRec ); vEnt = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vLC  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vPL  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vRC  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Entity', vEnt ) > 0 );
      IF( vLC @<> '' ); AttrPutS( vLC, 'WFP Entity', vEnt, 'Local Currency' ); ENDIF;
      IF( vPL @<> '' ); AttrPutS( vPL, 'WFP Entity', vEnt, 'Primary Location' ); ENDIF;
      AttrPutS( vRC, 'WFP Entity', vEnt, 'Reporting Currency' );
   ENDIF;
END;

# --- WFP Version: Version Type (Calculated | Static), Description ---
vVr = 'Actual;Static;Actuals - non-calculating; loaded by WFP Load Actuals for closed months~Budget;Calculated;Approved plan being built~Forecast;Calculated;Working current model - closed months = Actual, open months own assumptions~Downside;Calculated;Self-contained downside (cost-pressure) scenario~Act vs Bud;Calculated;Actual minus Budget, closed periods only (positive = overspend)~Fcst vs Bud;Calculated;Forecast minus Budget - rolling outlook vs plan (use at FY)~Var FX;Calculated;FX effect within Act vs Bud (Reporting currency only)~Var Operational;Calculated;Operational effect within Act vs Bud (Reporting currency only)~';
WHILE( SCAN( '~', vVr ) > 1 );
   nS = SCAN( '~', vVr ); vRec = SUBST( vVr, 1, nS - 1 ) | ';'; vVr = SUBST( vVr, nS + 1, LONG( vVr ) - nS );
   nS = SCAN( ';', vRec ); vVer = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vTyp = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vDsc = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Version', vVer ) > 0 );
      AttrPutS( vTyp, 'WFP Version', vVer, 'Version Type' );
      AttrPutS( vDsc, 'WFP Version', vVer, 'Description' );
   ENDIF;
END;

# --- WFP Cost Centre: Function, CC Name ---
vCC = 'CC-ENG-PLT;R&D;Engineering - Platform~CC-ENG-APP;R&D;Engineering - Application~CC-PROD;R&D;Product Management~CC-SALES;S&M;Sales~CC-SALESOPS;S&M;Sales Operations~CC-MKT;S&M;Marketing~CC-CS;S&M;Customer Success~CC-FIN;G&A;Finance~CC-PPL;G&A;People & HR~CC-ITOPS;G&A;IT & Operations~CC-EXEC;G&A;Executive~';
WHILE( SCAN( '~', vCC ) > 1 );
   nS = SCAN( '~', vCC ); vRec = SUBST( vCC, 1, nS - 1 ) | ';'; vCC = SUBST( vCC, nS + 1, LONG( vCC ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vFun = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vNam = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutS( vFun, 'WFP Cost Centre', vCtr, 'Function' );
      AttrPutS( vNam, 'WFP Cost Centre', vCtr, 'CC Name' );
   ENDIF;
END;

# --- WFP Pay Component: GL Account (P5 - P&L / GL mapping) ---
# Leaf pay components -> GL account code. GL rollup nodes carry the code too.
vPC = 'Base;6000~One-Time;6010~Bonus;6100~Employer Payroll Tax;6200~Employer Pension;6300~Benefits;6400~Employee Income Tax;7100~Employee Pension;7200~';
WHILE( SCAN( '~', vPC ) > 1 );
   nS = SCAN( '~', vPC ); vRec = SUBST( vPC, 1, nS - 1 ) | ';'; vPC = SUBST( vPC, nS + 1, LONG( vPC ) - nS );
   nS = SCAN( ';', vRec ); vEl  = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); vGL  = SUBST( vRec, 1, nS - 1 );
   IF( DIMIX( 'WFP Pay Component', vEl ) > 0 );
      AttrPutS( vGL, 'WFP Pay Component', vEl, 'GL Account' );
   ENDIF;
END;
IF( DIMIX( 'WFP Pay Component', 'GL: Salaries & Wages' ) > 0 );
   AttrPutS( '6000', 'WFP Pay Component', 'GL: Salaries & Wages', 'GL Account' );
   AttrPutS( '6100', 'WFP Pay Component', 'GL: Bonus & Incentives', 'GL Account' );
   AttrPutS( '6200', 'WFP Pay Component', 'GL: Employer Payroll Taxes', 'GL Account' );
   AttrPutS( '6300', 'WFP Pay Component', 'GL: Employer Pension', 'GL Account' );
   AttrPutS( '6400', 'WFP Pay Component', 'GL: Benefits', 'GL Account' );
ENDIF;

# --- WFP Cost Centre: Capex % (P5 - share of loaded Cost-to-Company capitalised) ---
# R&D engineering / product cost centres capitalise 18% of CtC; everything else 0.
vCX = 'CC-ENG-PLT;0.18~CC-ENG-APP;0.18~CC-PROD;0.18~CC-SALES;0~CC-SALESOPS;0~CC-MKT;0~CC-CS;0~CC-FIN;0~CC-PPL;0~CC-ITOPS;0~CC-EXEC;0~';
WHILE( SCAN( '~', vCX ) > 1 );
   nS = SCAN( '~', vCX ); vRec = SUBST( vCX, 1, nS - 1 ) | ';'; vCX = SUBST( vCX, nS + 1, LONG( vCX ) - nS );
   nS = SCAN( ';', vRec ); vCtr = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
   nS = SCAN( ';', vRec ); nPct = NUMBR( SUBST( vRec, 1, nS - 1 ) );
   IF( DIMIX( 'WFP Cost Centre', vCtr ) > 0 );
      AttrPutN( nPct, 'WFP Cost Centre', vCtr, 'Capex %' );
   ENDIF;
END;
#EndRegion

rules::WFP Headcount.rules:
SKIPCHECK;

# Non-calculating versions (Actual + snapshots) hold stored data.
[] = N: IF(ELPAR('WFP Version', !WFP Version, 1) @= 'Non-Calculating', STET, CONTINUE);

# ===== Variance versions (P6) =====
['Act vs Bud'] = N:
  IF( ATTRN('WFP Period', !WFP Period, 'Actuals Closed') = 1,
      DB('WFP Headcount', !WFP Period, 'Actual', !WFP Entity, !WFP Cost Centre, !WFP Position, !WFP Headcount Measure)
    - DB('WFP Headcount', !WFP Period, 'Budget', !WFP Entity, !WFP Cost Centre, !WFP Position, !WFP Headcount Measure), 0 );

['Fcst vs Bud'] = N:
      DB('WFP Headcount', !WFP Period, 'Forecast', !WFP Entity, !WFP Cost Centre, !WFP Position, !WFP Headcount Measure)
    - DB('WFP Headcount', !WFP Period, 'Budget', !WFP Entity, !WFP Cost Centre, !WFP Position, !WFP Headcount Measure);

# WFP Headcount dims: Period, Version, Entity, Cost Centre, Position, Measure
# Phase 4: active window is version-aware — WFP Hiring Plan Hire/Attrition Month
# for the version, falling back to Start/End Period attrs when the plan cell is 0.
# TBH positions with no plan hire are never active.

['_Start Idx'] = N:
  IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0,
      DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'),
      IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'TBH', 9999,
          ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index') ) );

['_Leave Idx'] = N:
  IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Attrition Month') > 0,
      DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Attrition Month'),
      IF( ATTRS('WFP Position', !WFP Position, 'End Period') @= '', 9999,
          ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'End Period'), 'Period Index') + 1 ) );

['_End Idx'] = N: ['_Leave Idx'] - 1;

['_Hire Idx'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled',
      ATTRN('WFP Period', ATTRS('WFP Position', !WFP Position, 'Start Period'), 'Period Index'),
      IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0,
          DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'), 0 ) );

['_Active'] = N:
  IF( !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre')
      & ATTRN('WFP Period', !WFP Period, 'Period Index') >= ['_Start Idx']
      & ATTRN('WFP Period', !WFP Period, 'Period Index') <= ['_End Idx'],
      1, 0 );

['_Filled Now'] = N:
  IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Filled', 1,
      IF( DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month') > 0
          & ATTRN('WFP Period', !WFP Period, 'Period Index') >= DB('WFP Hiring Plan', !WFP Version, !WFP Position, 'Hire Month'), 1, 0 ) );

['Headcount'] = N: ['_Active'] * ['_Filled Now'];

['FTE'] = N:
  ['_Active'] * ATTRN('WFP Position', !WFP Position, 'FTE')
  * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'TBH', ['_Filled Now'], 1 );

['Open Positions'] = N:
  ['_Active'] * IF( ATTRS('WFP Position', !WFP Position, 'Position Status') @= 'Open Req',
                    IF( ['_Filled Now'] = 1, 0, 1 ), 0 );

['Hires'] = N:
  IF( ['_Hire Idx'] >= 13
      & ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_Hire Idx']
      & ['_Active'] = 1, 1, 0 );

['Leavers'] = N:
  IF( ['_Leave Idx'] < 9999
      & ATTRN('WFP Period', !WFP Period, 'Period Index') = ['_Leave Idx']
      & !WFP Entity @= ATTRS('WFP Position', !WFP Position, 'Home Entity')
      & !WFP Cost Centre @= ATTRS('WFP Position', !WFP Position, 'Cost Centre'), 1, 0 );

['Opening'] = N:
  IF( ATTRS('WFP Period', !WFP Period, 'Prior Period') @= '', 0,
      DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Prior Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Headcount') );

['Closing'] = N: ['Opening'] + ['Hires'] - ['Leavers'];

FEEDERS;

['Headcount'] => ['FTE'], ['Open Positions'], ['Hires'], ['Opening'], ['Closing'];
['FTE']       => ['Open Positions'], ['Opening'], ['Closing'];
# Leavers fire the month AFTER headcount drops to 0 — feed forward via Next Period.
['Headcount'] => DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Leavers'),
                 DB('WFP Headcount', ATTRS('WFP Period', !WFP Period, 'Next Period'), !WFP Version, !WFP Entity, !WFP Cost Centre, !WFP Position, 'Closing');

# P6 — variance versions
['Actual']   => ['Act vs Bud'];
['Budget']   => ['Act vs Bud'], ['Fcst vs Bud'];
['Forecast'] => ['Fcst vs Bud'];

process::WFP Build YTD Hierarchy.PrologProcedure:
#Region WFP Build YTD Hierarchy — alternate rollup on WFP Period
# For each real month YYYY-MM creates a consolidation "YTD YYYY-MM" that sums
# every month in the same fiscal year with Period Index <= this month's.
# Idempotent — re-adding an element / edge is a no-op. Run after the period
# dimension exists; safe to re-run any time.
cPer = 'WFP Period';
nCount = DIMSIZ( cPer );

# Pass 1 — create the YTD consolidation members
nI = 1;
WHILE( nI <= nCount );
   vP = DIMNM( cPer, nI );
   IF( DTYPE( cPer, vP ) @= 'N' & LONG( vP ) = 7 & SUBST( vP, 5, 1 ) @= '-' );
      DimensionElementInsertDirect( cPer, '', 'YTD ' | vP, 'C' );
   ENDIF;
   nI = nI + 1;
END;

# Pass 2 — wire each month into every YTD member for its FY at or after it
nI = 1;
WHILE( nI <= nCount );
   vP = DIMNM( cPer, nI );
   IF( DTYPE( cPer, vP ) @= 'N' & LONG( vP ) = 7 & SUBST( vP, 5, 1 ) @= '-' );
      vFY   = ATTRS( cPer, vP, 'FY' );
      nIdx  = ATTRN( cPer, vP, 'Period Index' );
      nJ = 1;
      WHILE( nJ <= nCount );
         vT = DIMNM( cPer, nJ );
         IF( DTYPE( cPer, vT ) @= 'N' & LONG( vT ) = 7 & SUBST( vT, 5, 1 ) @= '-'
             & ATTRS( cPer, vT, 'FY' ) @= vFY
             & ATTRN( cPer, vT, 'Period Index' ) >= nIdx );
            DimensionElementComponentAddDirect( cPer, 'YTD ' | vT, vP, 1 );
         ENDIF;
         nJ = nJ + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

process::WFP Load Actuals.PrologProcedure:
#Region WFP Load Actuals — populate the Actual (static) version for closed months
# DEMO GENERATOR. In production this process's datasource becomes the payroll
# extract. Here Actual is derived from Forecast for the closed window (period
# index 13..15 = 2026-01..03) plus deliberate deltas so the variance layer has
# something to show:
#   * ENG-006 (NZ) left end of Feb 2026 - unplanned early departure; 12,000 NZD
#     severance paid in Mar (a month with no base pay).
#   * SLS-001 (UK) 5,000 GBP discretionary bonus in Feb.
#   * USD ran weaker than plan: 0.77 vs the 0.79 budget/forecast rate, Jan-Mar.
# Idempotent - CellPutN writes absolute values; re-run overwrites.

cWC  = 'WFP Workforce Cost';
cWI  = 'WFP Workforce Input';
cHC  = 'WFP Headcount';
cFX  = 'WFP FX Rates';
cPos = 'WFP Position';
cPer = 'WFP Period';
cCC  = 'WFP Cost Centre';

nWinFrom = 13;
nWinTo   = 15;
nActUSD  = 0.77;
nBudUSD  = 0.79;
nRateNZD = 0.47;
nRateGBP = 1;

nPerCount = DIMSIZ( cPer );
nPosCount = DIMSIZ( cPos );

# ---- 1. Actual FX rates for the closed window ----
nP = 1;
WHILE( nP <= nPerCount );
   vPer = DIMNM( cPer, nP );
   IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
      nIdx = ATTRN( cPer, vPer, 'Period Index' );
      IF( nIdx >= nWinFrom & nIdx <= nWinTo );
         CellPutN( nRateGBP, cFX, vPer, 'Actual', 'GBP',       'Average', 'Rate' );
         CellPutN( nRateGBP, cFX, vPer, 'Actual', 'GBP',       'Closing', 'Rate' );
         CellPutN( nActUSD,  cFX, vPer, 'Actual', 'USD',       'Average', 'Rate' );
         CellPutN( nActUSD,  cFX, vPer, 'Actual', 'USD',       'Closing', 'Rate' );
         CellPutN( nRateNZD, cFX, vPer, 'Actual', 'NZD',       'Average', 'Rate' );
         CellPutN( nRateNZD, cFX, vPer, 'Actual', 'NZD',       'Closing', 'Rate' );
         CellPutN( nRateGBP, cFX, vPer, 'Actual', 'Reporting', 'Average', 'Rate' );
         CellPutN( nRateGBP, cFX, vPer, 'Actual', 'Reporting', 'Closing', 'Rate' );
      ENDIF;
   ENDIF;
   nP = nP + 1;
END;

# ---- 2. Copy Forecast -> Actual for the closed window ----
vAllComps = 'Base|Employer Payroll Tax|Employer Pension|Benefits|Bonus|One-Time|Gross Pay|Employee Income Tax|Employee Pension|Net Pay|';
vHcMeas   = 'Headcount|FTE|Open Positions|Hires|Leavers|Opening|Closing|';

nI = 1;
WHILE( nI <= nPosCount );
   vPos = DIMNM( cPos, nI );
   IF( DTYPE( cPos, vPos ) @= 'N' );
      vHome = ATTRS( cPos, vPos, 'Home Entity' );
      vCtr  = ATTRS( cPos, vPos, 'Cost Centre' );
      vSC   = ATTRS( cPos, vPos, 'Salary Currency' );
      nCapexPct = ATTRN( cCC, vCtr, 'Capex %' );
      nRepRate    = IF( vSC @= 'USD', nActUSD, IF( vSC @= 'NZD', nRateNZD, nRateGBP ) );
      nRepBudRate = IF( vSC @= 'USD', nBudUSD, IF( vSC @= 'NZD', nRateNZD, nRateGBP ) );

      nP = 1;
      WHILE( nP <= nPerCount );
         vPer = DIMNM( cPer, nP );
         IF( DTYPE( cPer, vPer ) @= 'N' & LONG( vPer ) = 7 & SUBST( vPer, 5, 1 ) @= '-' );
            nIdx = ATTRN( cPer, vPer, 'Period Index' );
            IF( nIdx >= nWinFrom & nIdx <= nWinTo );

               nGone = IF( vPos @= 'ENG-006' & nIdx >= 15, 1, 0 );

               vL = vAllComps;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vPC = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  nLocal = IF( nGone = 1, 0, CellGetN( cWC, vPer, 'Forecast', vHome, vCtr, vPC, vSC, vPos, 'Amount' ) );
                  nIsCtc = IF( vPC @= 'Base' % vPC @= 'Employer Payroll Tax' % vPC @= 'Employer Pension' % vPC @= 'Benefits', 1, 0 );
                  nCapL  = nLocal * nCapexPct * nIsCtc;
                  nRep    = nLocal * nRepRate;
                  nRepBud = nLocal * nRepBudRate;
                  CellPutN( nLocal,          cWC, vPer, 'Actual', vHome, vCtr, vPC, vSC,                     vPos, 'Amount' );
                  CellPutN( nCapL,           cWC, vPer, 'Actual', vHome, vCtr, vPC, vSC,                     vPos, 'Amount Capex' );
                  CellPutN( nLocal - nCapL,  cWC, vPer, 'Actual', vHome, vCtr, vPC, vSC,                     vPos, 'Amount Opex' );
                  CellPutN( nRep,                     cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting',              vPos, 'Amount' );
                  CellPutN( nRep * nCapexPct * nIsCtc,cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting',              vPos, 'Amount Capex' );
                  CellPutN( nRep - nRep * nCapexPct * nIsCtc, cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting',      vPos, 'Amount Opex' );
                  CellPutN( nRepBud,                        cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting @ Budget FX', vPos, 'Amount' );
                  CellPutN( nRepBud * nCapexPct * nIsCtc,   cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting @ Budget FX', vPos, 'Amount Capex' );
                  CellPutN( nRepBud - nRepBud * nCapexPct * nIsCtc, cWC, vPer, 'Actual', vHome, vCtr, vPC, 'Reporting @ Budget FX', vPos, 'Amount Opex' );
               END;

               CellPutN( IF( nGone = 1, 0, CellGetN( cWI, vPer, 'Forecast', vPos, 'FTE' ) ),         cWI, vPer, 'Actual', vPos, 'FTE' );
               CellPutN( IF( nGone = 1, 0, CellGetN( cWI, vPer, 'Forecast', vPos, 'Base Salary' ) ), cWI, vPer, 'Actual', vPos, 'Base Salary' );

               vL = vHcMeas;
               WHILE( SCAN( '|', vL ) > 1 );
                  nS = SCAN( '|', vL ); vHM = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
                  CellPutN( CellGetN( cHC, vPer, 'Forecast', vHome, vCtr, vPos, vHM ), cHC, vPer, 'Actual', vHome, vCtr, vPos, vHM );
               END;
            ENDIF;
         ENDIF;
         nP = nP + 1;
      END;
   ENDIF;
   nI = nI + 1;
END;

# ---- 3. Deltas ----
# ENG-006 leaves end Feb: headcount bridge
CellPutN( 0, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Headcount' );
CellPutN( 0, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'FTE' );
CellPutN( 0, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Hires' );
CellPutN( 1, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Leavers' );
CellPutN( 1, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Opening' );
CellPutN( 0, cHC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Closing' );
CellPutN( 1, cHC, '2026-02', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'ENG-006', 'Closing' );

# ENG-006 severance 12,000 NZD in Mar (no base pay that month)
nSev = 12000;
CellPutN( nSev,             cWI, '2026-03', 'Actual', 'ENG-006', 'One-Time Amount' );
CellPutN( nSev,             cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'NZD',                    'ENG-006', 'Amount' );
CellPutN( nSev,             cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'NZD',                    'ENG-006', 'Amount Opex' );
CellPutN( nSev * nRateNZD,  cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'Reporting',              'ENG-006', 'Amount' );
CellPutN( nSev * nRateNZD,  cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'Reporting',              'ENG-006', 'Amount Opex' );
CellPutN( nSev * nRateNZD,  cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'Reporting @ Budget FX',  'ENG-006', 'Amount' );
CellPutN( nSev * nRateNZD,  cWC, '2026-03', 'Actual', 'NZ Ltd', 'CC-ENG-PLT', 'One-Time', 'Reporting @ Budget FX',  'ENG-006', 'Amount Opex' );

# SLS-001 discretionary bonus 5,000 GBP in Feb
nDisc = 5000;
CellPutN( nDisc, cWI, '2026-02', 'Actual', 'SLS-001', 'One-Time Amount' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'GBP',                    'SLS-001', 'Amount' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'GBP',                    'SLS-001', 'Amount Opex' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'Reporting',              'SLS-001', 'Amount' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'Reporting',              'SLS-001', 'Amount Opex' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'Reporting @ Budget FX',  'SLS-001', 'Amount' );
CellPutN( nDisc, cWC, '2026-02', 'Actual', 'UK Ltd', 'CC-SALES', 'One-Time', 'Reporting @ Budget FX',  'SLS-001', 'Amount Opex' );

# ---- 4. mark closed periods ----
AttrPutN( 1, cPer, '2026-01', 'Actuals Closed' );
AttrPutN( 1, cPer, '2026-02', 'Actuals Closed' );
AttrPutN( 1, cPer, '2026-03', 'Actuals Closed' );
